async fn coordinator_wave_control_tracks_pause_running_and_rebroadcasts() {
    init_tracing();
    let ipc = IpcNamespace::new().unwrap();
    let handshake_address = ipc.handshake_endpoint();

    let (shutdown0_tx, shutdown0_rx) = oneshot::channel();
    let engine0_task = tokio::spawn({
        let handshake_address = handshake_address.clone();
        async move {
            let mut engine = setup_mock_engine_sockets(handshake_address, &[0x00, 0x00]).await;
            let coordinator_address = engine
                .init
                .addresses
                .coordinator_input
                .clone()
                .expect("coordinator input address should be present");
            let mut coordinator =
                engine.coordinator.take().expect("coordinator sockets should be present");
            let data_socket = engine.data_sockets.first_mut().expect("data socket");

            // An idle engine handed a request starts the wave itself.
            let add = recv_engine_message(&mut data_socket.dealer).await;
            assert_eq!(add[0].as_ref(), &[0x00]);
            let request: EngineCoreRequest = rmp_serde::from_slice(&add[1]).unwrap();
            assert_eq!(request.request_id, "req-1");
            assert_eq!(request.current_wave, 0);
            send_start_wave(&mut coordinator.output_push, 0, 0).await;

            let (wave, exclude_engine) = recv_start_dp_wave(&mut coordinator.input_sub).await;
            assert_eq!((wave, exclude_engine), (0, Some(0)));

            let mut late_subscriber = SubSocket::new();
            late_subscriber.connect(&coordinator_address).await.unwrap();
            late_subscriber.subscribe("").await.unwrap();

            let replay = recv_start_dp_wave(&mut late_subscriber).await;
            assert_eq!(replay, (0, None));
            let replay = recv_start_dp_wave(&mut coordinator.input_sub).await;
            assert_eq!(replay, (0, None));

            assert!(
                timeout(
                    Duration::from_millis(200),
                    recv_start_dp_wave(&mut coordinator.input_sub)
                )
                .await
                .is_err()
            );

            send_outputs(
                &mut data_socket.push,
                RequestBatchOutputs {
                    outputs: vec![request_output(
                        "req-1",
                        vec![],
                        Some(EngineCoreFinishReason::Length),
                    )],
                    finished_requests: Some(BTreeSet::from(["req-1".to_string()])),
                    ..Default::default()
                }
                .into(),
            )
            .await;

            send_outputs(
                &mut coordinator.output_push,
                DpControlOutput {
                    engine_index: 0,
                    timestamp: 0.0,
                    control: DpControlMessage::WaveComplete(0),
                }
                .into(),
            )
            .await;

            let add = recv_engine_message(&mut data_socket.dealer).await;
            assert_eq!(add[0].as_ref(), &[0x00]);
            let request: EngineCoreRequest = rmp_serde::from_slice(&add[1]).unwrap();
            assert_eq!(request.request_id, "req-3");
            assert_eq!(request.current_wave, 1);
            send_start_wave(&mut coordinator.output_push, 0, 1).await;

            let (wave, exclude_engine) = recv_start_dp_wave(&mut coordinator.input_sub).await;
            assert_eq!((wave, exclude_engine), (1, Some(0)));

            send_outputs(
                &mut data_socket.push,
                RequestBatchOutputs {
                    outputs: vec![request_output(
                        "req-3",
                        vec![],
                        Some(EngineCoreFinishReason::Length),
                    )],
                    finished_requests: Some(BTreeSet::from(["req-3".to_string()])),
                    ..Default::default()
                }
                .into(),
            )
            .await;

            let _ = shutdown0_rx.await;
        }
    });

    let (shutdown1_tx, shutdown1_rx) = oneshot::channel();
    let engine1_task = tokio::spawn({
        let handshake_address = handshake_address.clone();
        async move {
            let mut engine = setup_mock_engine_sockets(handshake_address, &[0x01, 0x00]).await;
            let mut coordinator =
                engine.coordinator.take().expect("coordinator sockets should be present");
            let data_socket = engine.data_sockets.first_mut().expect("data socket");

            let (wave, exclude_engine) = recv_start_dp_wave(&mut coordinator.input_sub).await;
            assert_eq!((wave, exclude_engine), (0, Some(0)));
            let replay = recv_start_dp_wave(&mut coordinator.input_sub).await;
            assert_eq!(replay, (0, None));

            let add = recv_engine_message(&mut data_socket.dealer).await;
            assert_eq!(add[0].as_ref(), &[0x00]);
            let request: EngineCoreRequest = rmp_serde::from_slice(&add[1]).unwrap();
            assert_eq!(request.request_id, "req-2");
            assert_eq!(request.current_wave, 0);

            assert!(
                timeout(
                    Duration::from_millis(200),
                    recv_start_dp_wave(&mut coordinator.input_sub)
                )
                .await
                .is_err()
            );

            send_outputs(
                &mut data_socket.push,
                RequestBatchOutputs {
                    engine_index: 1,
                    outputs: vec![request_output(
                        "req-2",
                        vec![],
                        Some(EngineCoreFinishReason::Length),
                    )],
                    finished_requests: Some(BTreeSet::from(["req-2".to_string()])),
                    ..Default::default()
                }
                .into(),
            )
            .await;

            let (wave, exclude_engine) = recv_start_dp_wave(&mut coordinator.input_sub).await;
            assert_eq!((wave, exclude_engine), (1, Some(0)));

            assert!(
                timeout(
                    Duration::from_millis(200),
                    recv_engine_message(&mut data_socket.dealer)
                )
                .await
                .is_err()
            );

            let _ = shutdown1_rx.await;
        }
    });

    let client = connect_client_with_ipc(
        handshake_test_config(
            handshake_address,
            2,
            "test-model",
            Duration::from_secs(2),
            0,
            Some(CoordinatorMode::InProc),
        ),
        &ipc,
    )
    .await;

    let mut stream_1 = client.call(sample_request_with_id("req-1")).await.unwrap().into_outputs();
    let mut stream_2 = client.call(sample_request_with_id("req-2")).await.unwrap().into_outputs();

    let final_1 = timeout(Duration::from_secs(1), stream_1.next())
        .await
        .unwrap()
        .unwrap()
        .unwrap();
    assert_eq!(final_1.request_id, "req-1");
    assert_eq!(final_1.finish_reason, Some(EngineCoreFinishReason::Length));
    assert!(timeout(Duration::from_secs(1), stream_1.next()).await.unwrap().is_none());

    let final_2 = timeout(Duration::from_secs(1), stream_2.next())
        .await
        .unwrap()
        .unwrap()
        .unwrap();
    assert_eq!(final_2.request_id, "req-2");
    assert_eq!(final_2.finish_reason, Some(EngineCoreFinishReason::Length));
    assert!(timeout(Duration::from_secs(1), stream_2.next()).await.unwrap().is_none());

    tokio::time::sleep(Duration::from_millis(100)).await;

    let mut stream_3 = client.call(sample_request_with_id("req-3")).await.unwrap().into_outputs();
    let final_3 = timeout(Duration::from_secs(1), stream_3.next())
        .await
        .unwrap()
        .unwrap()
        .unwrap();
    assert_eq!(final_3.request_id, "req-3");
    assert_eq!(final_3.finish_reason, Some(EngineCoreFinishReason::Length));
    assert!(timeout(Duration::from_secs(1), stream_3.next()).await.unwrap().is_none());

    tokio::time::sleep(Duration::from_millis(100)).await;

    let _ = shutdown0_tx.send(());
    let _ = shutdown1_tx.send(());
    engine0_task.await.unwrap();
    engine1_task.await.unwrap();
    client.shutdown().await.unwrap();
}

async fn coordinator_rebroadcasts_engine_start_wave_control() {
    init_tracing();
    let ipc = IpcNamespace::new().unwrap();
    let handshake_address = ipc.handshake_endpoint();

    let (shutdown0_tx, shutdown0_rx) = oneshot::channel();
    let engine0_task = tokio::spawn({
        let handshake_address = handshake_address.clone();
        async move {
            let mut engine = setup_mock_engine_sockets(handshake_address, &[0x00, 0x00]).await;
            let mut coordinator =
                engine.coordinator.take().expect("coordinator sockets should be present");

            let (wave, exclude_engine) = recv_start_dp_wave(&mut coordinator.input_sub).await;
            assert_eq!((wave, exclude_engine), (4, Some(1)));

            let _ = shutdown0_rx.await;
        }
    });

    let (shutdown1_tx, shutdown1_rx) = oneshot::channel();
    let engine1_task = tokio::spawn({
        let handshake_address = handshake_address.clone();
        async move {
            let mut engine = setup_mock_engine_sockets(handshake_address, &[0x01, 0x00]).await;
            let mut coordinator =
                engine.coordinator.take().expect("coordinator sockets should be present");

            send_outputs(
                &mut coordinator.output_push,
                DpControlOutput {
                    engine_index: 1,
                    timestamp: 0.0,
                    control: DpControlMessage::StartWave(4),
                }
                .into(),
            )
            .await;

            let (wave, exclude_engine) = recv_start_dp_wave(&mut coordinator.input_sub).await;
            assert_eq!((wave, exclude_engine), (4, Some(1)));

            let _ = shutdown1_rx.await;
        }
    });

    let client = connect_client_with_ipc(
        handshake_test_config(
            handshake_address,
            2,
            "test-model",
            Duration::from_secs(2),
            0,
            Some(CoordinatorMode::InProc),
        ),
        &ipc,
    )
    .await;

    tokio::time::sleep(Duration::from_millis(200)).await;

    let _ = shutdown0_tx.send(());
    let _ = shutdown1_tx.send(());
    engine0_task.await.unwrap();
    engine1_task.await.unwrap();
    client.shutdown().await.unwrap();
}

async fn coordinator_publishes_wave_state_to_frontend_subscribers() {
    init_tracing();
    let ipc = IpcNamespace::new().unwrap();
    let handshake_address = ipc.handshake_endpoint();

    let (init_tx, init_rx) = oneshot::channel();
    let (subscribed_tx, subscribed_rx) = oneshot::channel();
    let (shutdown_tx, shutdown_rx) = oneshot::channel();
    let engine_task = tokio::spawn(async move {
        let mut engine = setup_mock_engine_sockets(handshake_address, &[0x00, 0x00]).await;
        let mut coordinator =
            engine.coordinator.take().expect("coordinator sockets should be present");

        // Finish wave 0 and start wave 1 before any frontend subscribes. The
        // `START_DP_WAVE` broadcast shows the coordinator processed both.
        send_start_wave(&mut coordinator.output_push, 0, 0).await;
        assert_eq!(
            recv_start_dp_wave(&mut coordinator.input_sub).await,
            (0, Some(0))
        );
        send_outputs(
            &mut coordinator.output_push,
            DpControlOutput {
                engine_index: 0,
                timestamp: 0.0,
                control: DpControlMessage::WaveComplete(0),
            }
            .into(),
        )
        .await;
        send_start_wave(&mut coordinator.output_push, 0, 1).await;
        assert_eq!(
            recv_start_dp_wave(&mut coordinator.input_sub).await,
            (1, Some(0))
        );
        let _ = init_tx.send(engine.init.clone());

        subscribed_rx.await.unwrap();
        send_outputs(
            &mut coordinator.output_push,
            DpControlOutput {
                engine_index: 0,
                timestamp: 0.0,
                control: DpControlMessage::WaveComplete(1),
            }
            .into(),
        )
        .await;

        let _ = shutdown_rx.await;
    });

    let client = connect_client_with_ipc(
        handshake_test_config(
            ipc.handshake_endpoint(),
            1,
            "test-model",
            Duration::from_secs(2),
            0,
            Some(CoordinatorMode::InProc),
        ),
        &ipc,
    )
    .await;

    let init = init_rx.await.unwrap();
    let publish_address = init
        .addresses
        .frontend_stats_publish_address
        .expect("frontend publish address should be present");
    let mut frontend = SubSocket::new();
    frontend.connect(&publish_address).await.unwrap();
    frontend.subscribe("").await.unwrap();

    // The wave-only publish `(None, wave, engines_running)` as a msgpack
    // array. A frontend subscribing mid-wave first receives the current state.
    assert_eq!(recv_coordinator_publish(&mut frontend).await, "93c001c3");

    // A wave transition still pending when the frontend subscribed may publish
    // the same state again; the next distinct state is the one that follows.
    subscribed_tx.send(()).unwrap();
    let next_state = loop {
        let state = recv_coordinator_publish(&mut frontend).await;
        if state != "93c001c3" {
            break state;
        }
    };
    assert_eq!(next_state, "93c002c2");

    let _ = shutdown_tx.send(());
    engine_task.await.unwrap();
    client.shutdown().await.unwrap();
}

